function singleMailbox(value) {
  if (typeof value !== "string" || /[\r\n\x00]/.test(value)) return "";
  const text = value.trim();
  const named = text.match(/^(?:[^<>,;]+|"[^"\r\n]+")\s*<([^<>]+)>$/);
  const address = named ? named[1] : text;
  return /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(address) &&
    address.length <= 254
    ? address
    : "";
}
export default ({ folder, reviewer, mailbox }) => {
  if (
    !folder.trim() ||
    !singleMailbox(reviewer) ||
    !singleMailbox(mailbox) ||
    reviewer.endsWith(".invalid") ||
    mailbox.endsWith(".invalid")
  ) {
    throw Error("Set the inbox, SMTP mailbox and reviewer addresses.");
  }
  return { folder, reviewer, mailbox };
};

