export default async ({ approval }, context) => {
  const { inputs, action, comment } = approval;
  if (action !== "approve" || typeof comment !== "string" || comment.trim() !== inputs.reviewCode) {
    throw Error("The approval did not contain this email’s review code.");
  }
  const send = await context.state.insert("send:" + inputs.key, { status: "pending" });
  return {
    send,
    recipient: inputs.sender,
    subject: "Re: " + inputs.subject,
    text: inputs.draft,
    key: inputs.key,
  };
};

