export default async ({ recipient, subject, text, key }, context) => {
  const reply = await context.actions.call("generic_imap.send_email", {
    to: [recipient],
    subject,
    text,
  });
  const messageId = smtpAccepted(reply, recipient);
  await context.state.set("send:" + key, { status: "accepted", messageId });
  return { messageId };
};
